// Recuperer l'incident venant du node precedent
const incident = $input.first().json;

// Mini CMDB simule (en production : Google Sheets / ServiceNow / API interne)
const cmdb = {
  "SVC-PAY-001": {
    name: "Plateforme de paiement en ligne",
    criticality: "critical",
    is_critical_function: true,
    business_owner: "Direction Paiements",
    rto_minutes: 60
  },
  "SVC-CORE-002": {
    name: "Core banking",
    criticality: "critical",
    is_critical_function: true,
    business_owner: "Direction SI Bancaire",
    rto_minutes: 30
  },
  "SVC-CRM-003": {
    name: "CRM commercial",
    criticality: "non_critical",
    is_critical_function: false,
    business_owner: "Direction Commerciale",
    rto_minutes: 480
  }
};

// Lookup de la criticite du service
const serviceInfo = cmdb[incident.affected_service_id] || {
  name: "Service inconnu",
  criticality: "unknown",
  is_critical_function: false
};

// Estimation de l'impact economique (regle simplifiee POC)
// 50 EUR par client impacte + 10 000 EUR par heure de downtime pour service critique
const downtimeCost = serviceInfo.is_critical_function
  ? (incident.duration_minutes_so_far / 60) * 10000
  : 0;
const clientImpactCost = (incident.estimated_clients_affected || 0) * 50;
const economicImpactEur = Math.round(downtimeCost + clientImpactCost);

// Renvoyer l'incident enrichi
return [{
  json: {
    ...incident,
    service_info: serviceInfo,
    economic_impact_eur: economicImpactEur,
    enriched_at: new Date().toISOString()
  }
}];

